#!/usr/bin/env Rscript

add_pwa_wrapper <- function(site_dir, source_dir = NULL) {
  site_dir <- normalizePath(site_dir, mustWork = TRUE)

  if (is.null(source_dir)) {
    cmd <- commandArgs(trailingOnly = FALSE)
    file_arg <- grep("^--file=", cmd, value = TRUE)
    source_dir <- if (length(file_arg)) {
      dirname(normalizePath(sub("^--file=", "", file_arg[[1]]), mustWork = TRUE))
    } else {
      normalizePath(".", mustWork = TRUE)
    }
  } else {
    source_dir <- normalizePath(source_dir, mustWork = TRUE)
  }

  pwa_dir <- file.path(source_dir, "pwa")
  required <- c(
    "manifest.webmanifest",
    "service-worker.js",
    "install-pwa.js",
    "pwa-shell.css",
    "icons/apple-touch-icon.png",
    "icons/favicon-32.png",
    "icons/icon-192.png",
    "icons/icon-512.png",
    "icons/icon-maskable-512.png"
  )

  missing <- required[!file.exists(file.path(pwa_dir, required))]
  if (length(missing)) {
    stop("Missing PWA source file(s):\n- ", paste(missing, collapse = "\n- "))
  }

  dir.create(file.path(site_dir, "icons"), recursive = TRUE, showWarnings = FALSE)

  top_level <- c(
    "manifest.webmanifest",
    "service-worker.js",
    "install-pwa.js",
    "pwa-shell.css"
  )

  for (item in top_level) {
    ok <- file.copy(
      file.path(pwa_dir, item),
      file.path(site_dir, item),
      overwrite = TRUE
    )
    if (!isTRUE(ok)) stop("Could not copy PWA file: ", item)
  }

  icon_files <- list.files(file.path(pwa_dir, "icons"), full.names = TRUE)
  ok <- file.copy(icon_files, file.path(site_dir, "icons"), overwrite = TRUE)
  if (!all(ok)) stop("Could not copy one or more PWA icons.")

  index_file <- file.path(site_dir, "index.html")
  if (!file.exists(index_file)) stop("Missing exported index.html: ", index_file)

  html <- paste(readLines(index_file, warn = FALSE, encoding = "UTF-8"), collapse = "\n")

  # Make repeated export/post-processing idempotent.
  html <- gsub(
    "(?s)\\s*<!-- DOG2-PWA-HEAD-BEGIN -->.*?<!-- DOG2-PWA-HEAD-END -->",
    "",
    html,
    perl = TRUE
  )
  html <- gsub(
    "(?s)\\s*<!-- DOG2-PWA-BODY-BEGIN -->.*?<!-- DOG2-PWA-BODY-END -->",
    "",
    html,
    perl = TRUE
  )

  viewport_pattern <- "<meta[^>]+name=['\"]viewport['\"][^>]*>"
  viewport_tag <- '<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">'
  if (grepl(viewport_pattern, html, ignore.case = TRUE, perl = TRUE)) {
    html <- sub(viewport_pattern, viewport_tag, html, ignore.case = TRUE, perl = TRUE)
  }

  head_block <- paste0(
    "\n<!-- DOG2-PWA-HEAD-BEGIN -->\n",
    if (!grepl(viewport_pattern, html, ignore.case = TRUE, perl = TRUE)) paste0(viewport_tag, "\n") else "",
    '<link rel="manifest" href="./manifest.webmanifest">\n',
    '<meta name="theme-color" content="#0f5d75">\n',
    '<meta name="mobile-web-app-capable" content="yes">\n',
    '<meta name="apple-mobile-web-app-capable" content="yes">\n',
    '<meta name="apple-mobile-web-app-status-bar-style" content="default">\n',
    '<meta name="apple-mobile-web-app-title" content="DOG2 Predictor">\n',
    '<link rel="apple-touch-icon" sizes="180x180" href="./icons/apple-touch-icon.png">\n',
    '<link rel="icon" type="image/png" sizes="32x32" href="./icons/favicon-32.png">\n',
    '<link rel="stylesheet" href="./pwa-shell.css">\n',
    "<!-- DOG2-PWA-HEAD-END -->\n"
  )

  body_block <- paste0(
    "\n<!-- DOG2-PWA-BODY-BEGIN -->\n",
    '<script src="./install-pwa.js" defer></script>\n',
    "<!-- DOG2-PWA-BODY-END -->\n"
  )

  if (!grepl("</head>", html, ignore.case = TRUE)) stop("Could not find </head> in index.html")
  if (!grepl("</body>", html, ignore.case = TRUE)) stop("Could not find </body> in index.html")

  html <- sub("</head>", paste0(head_block, "</head>"), html, ignore.case = TRUE)
  html <- sub("</body>", paste0(body_block, "</body>"), html, ignore.case = TRUE)

  writeLines(enc2utf8(html), index_file, useBytes = TRUE)
  file.create(file.path(site_dir, ".nojekyll"))

  cat("PWA wrapper added to:\n", site_dir, "\n", sep = "")
  invisible(site_dir)
}

if (sys.nframe() == 0) {
  args <- commandArgs(trailingOnly = TRUE)
  if (length(args) < 1) {
    stop("Usage: Rscript add_pwa_wrapper.R <exported_site_dir> [source_app_dir]")
  }
  add_pwa_wrapper(
    site_dir = args[[1]],
    source_dir = if (length(args) >= 2) args[[2]] else NULL
  )
}

