library(shiny)



# SHINYLIVE-IOS-DOWNLOAD-WORKAROUND
# Removing the HTML `download` attribute avoids a Shinylive browser bug that
# can turn generated files into download_<id>.html. Keeping target="_blank"
# lets iOS open the file in a separate Safari/preview context.
downloadButton <- function(...) {
  tag <- shiny::downloadButton(...)
  tag$attribs$download <- NULL
  tag$attribs$target <- "_blank"
  tag
}

source("backend_shinylive.R", local = TRUE)

model_asset <- file.path("assets", "shinylive_model_bundle.rds")
mapping_asset <- file.path("assets", "dog_human_mapping.rds")
if (!file.exists(model_asset) || !file.exists(mapping_asset)) {
  stop(
    "Shinylive assets are missing. Run prepare_shinylive_assets.R first. ",
    "Expected: assets/shinylive_model_bundle.rds and assets/dog_human_mapping.rds"
  )
}

MODEL <- readRDS(model_asset)
MAPPING <- readRDS(mapping_asset)

safe_sample_id <- function(x) {
  x <- trimws(as.character(x))
  x <- gsub("[^A-Za-z0-9._-]+", "_", x)
  x <- gsub("^_+|_+$", "", x)
  if (!nzchar(x)) "Sample" else x
}

metric_table <- function(dat) {
  vals <- unlist(dat[1, , drop = FALSE], use.names = TRUE)
  data.frame(Metric = names(vals), Value = as.character(vals), stringsAsFactors = FALSE)
}

status_badge <- function(status) {
  cls <- switch(status, PASS = "qc-pass", WARNING = "qc-warning", FAIL = "qc-fail", "qc-warning")
  tags$span(class = paste("qc-badge", cls), status)
}

risk_card <- function(title, score, percentile, tertile) {
  div(
    class = "risk-card",
    h3(title),
    div(class = "risk-score", sprintf("%.3f", score)),
    div(class = "risk-label", "Frozen ridge-Cox log-hazard"),
    div(class = "percentile-value", sprintf("%.1f percentile", 100 * percentile)),
    div(class = "risk-label", "Relative to DOG2 training animals"),
    div(class = "tertile-label", tertile)
  )
}


# IOS-PWA-PDF-NAVIGATION-FIX
# Open the generated PDF outside the standalone iPhone PWA screen.
ios_pdf_download_button <- function(...) {
  tag <- shiny::downloadButton(...)

  tag$attribs$download <- NULL
  tag$attribs$target <- "_blank"
  tag$attribs$rel <- "noopener noreferrer"

  tag
}

ui <- navbarPage(
  title = "DOG2 all56 Predictor — Server-free",
  header = tags$head(

      tags$script(
        HTML(
          "
          // DOG2-IOS-PDF-SHARE
          window.dog2PdfFile = null;

          Shiny.addCustomMessageHandler('dog2-set-pdf', function(message) {
            const binary = atob(message.base64);
            const bytes = new Uint8Array(binary.length);
            for (let i = 0; i < binary.length; i++) {
              bytes[i] = binary.charCodeAt(i);
            }
            window.dog2PdfFile = new File(
              [bytes],
              message.filename,
              { type: 'application/pdf' }
            );
          });

          document.addEventListener('click', async function(event) {
            const button = event.target.closest('#share_pdf');
            if (!button) return;
            event.preventDefault();

            const file = window.dog2PdfFile;
            if (!file) {
              window.alert('Run prediction before saving the PDF report.');
              return;
            }

            try {
              const shareData = {
                files: [file],
                title: 'DOG2 prediction report'
              };
              if (
                navigator.share &&
                navigator.canShare &&
                navigator.canShare(shareData)
              ) {
                await navigator.share(shareData);
                return;
              }
            } catch (error) {
              if (error && error.name === 'AbortError') return;
              console.error('Native PDF sharing failed:', error);
            }

            const url = URL.createObjectURL(file);
            const link = document.createElement('a');
            link.href = url;
            link.download = file.name;
            document.body.appendChild(link);
            link.click();
            link.remove();
            window.setTimeout(function() {
              URL.revokeObjectURL(url);
            }, 60000);
          });
          "
        )
      ),
tags$link(rel = "stylesheet", type = "text/css", href = "app.css")),

  tabPanel(
    "Predict",
    div(
      class = "app-container",
      fluidRow(
        column(
          width = 4,
          wellPanel(
            h4("New sample"),
            textInput("sample_id", "Sample ID", value = ""),
            selectInput(
              "gene_id_type", "Gene identifier",
              choices = c(
                "Canine Ensembl ID" = "dog_ensembl",
                "Canine gene symbol" = "dog_symbol",
                "Human gene symbol" = "human_symbol"
              ),
              selected = "dog_ensembl"
            ),
            fileInput(
              "count_file", "Read-count / expression file",
              accept = c(".csv", ".tsv", ".txt", ".gz")
            ),
            checkboxInput(
              "omitted_rows_zero",
              "Treat absent gene rows as zero counts",
              value = FALSE
            ),
            div(
              class = "help-note",
              "Enable only when omitted rows truly mean zero. The uploaded file stays in this browser session."
            ),
            actionButton("run_prediction", "Run prediction", class = "btn-primary btn-block"),
            br(), br(),
            downloadButton("download_prediction", "Download prediction TSV", class = "btn-block"),
            br(), br(),
            actionButton(
            "share_pdf",
            "Save / share PDF",
            class = "w-100",
            icon = icon("file-pdf")
          )
          )
        ),
        column(
          width = 8,
          uiOutput("analysis_status"),
          conditionalPanel(
            condition = "output.has_result === true",
            tabsetPanel(
              tabPanel("Summary", uiOutput("risk_summary")),
              tabPanel(
                "QC",
                h4("Input quality control"),
                tableOutput("qc_table"),
                hr(),
                h4("Gene mapping"),
                tableOutput("mapping_table")
              ),
              tabPanel(
                "Contributions",
                h4("Top DFI model contributions"),
                tableOutput("dfi_table"),
                hr(),
                h4("Top OS model contributions"),
                tableOutput("os_table")
              ),
              tabPanel("All 56 signatures", tableOutput("all_table"))
            )
          )
        )
      )
    )
  ),

  tabPanel(
    "How to read",
    div(
      class = "app-container explanation-page",
      h2("How to interpret the result"),
      h4("DOG2 percentile"),
      p("The percentile is the sample's relative position in the DOG2 training score distribution."),
      p(strong("It is not a recurrence or mortality probability.")),
      h4("Frozen log-hazard score"),
      p("This is the frozen Cox-model linear predictor, not a predicted survival time."),
      h4("Research-use limitation"),
      p("The current model is research-use-only and is not prospectively clinically validated.")
    )
  ),

  tabPanel(
    "Install",
    div(
      class = "app-container explanation-page install-page",
      h2("Install as an iPhone-style app"),
      h4("iPhone or iPad"),
      tags$ol(
        tags$li("Open the GitHub Pages URL in Safari."),
        tags$li("Tap the Share button."),
        tags$li("Choose Add to Home Screen, then tap Add.")
      ),
      p("Launch the new DOG2 Predictor icon from the Home Screen. It opens without the normal browser address bar."),
      h4("Desktop or Android"),
      p("Use the browser's Install or Add to Home Screen command when it is offered."),
      h4("First launch and offline use"),
      p("The first launch downloads the browser-based R runtime. Keep the app open until it has fully loaded. Assets used by the app are then cached for later launches."),
      div(
        class = "interpretation-alert",
        strong("Research use only: "),
        "This PWA is an installable website, not an App Store clinical application."
      )
    )
  ),

  tabPanel(
    "Privacy & model",
    div(
      class = "app-container explanation-page",
      h2("Server-free processing"),
      p("The R runtime executes inside the browser. The uploaded expression file is not submitted to a Shiny compute server."),
      p("The static site necessarily distributes the frozen model bundle and gene mapping to each browser. Do not publish this version unless those assets may be publicly downloadable."),
      h4("Model"),
      p(MODEL$model_version),
      tags$ul(
        tags$li(paste(length(MODEL$signature_ids), "signatures")),
        tags$li(paste(length(MODEL$rank_genes), "rank-universe genes")),
        tags$li("Within-sample rank scoring"),
        tags$li("Frozen DFI and OS coefficient vectors")
      )
    )
  )
)

server <- function(input, output, session) {
  result <- reactiveVal(NULL)
  error_message <- reactiveVal(NULL)
  running <- reactiveVal(FALSE)

  output$has_result <- reactive(!is.null(result()))
  outputOptions(output, "has_result", suspendWhenHidden = FALSE)

  observeEvent(input$run_prediction, {
    result(NULL)
    error_message(NULL)
    req(input$count_file)
    sample_id <- trimws(input$sample_id)
    validate(need(nzchar(sample_id), "Enter a Sample ID."))
    running(TRUE)
    on.exit(running(FALSE), add = TRUE)

    ans <- tryCatch(
      withProgress(message = "Running in your browser", value = 0, {
        incProgress(0.2, detail = "Reading input")
        out <- predict_all56_browser(
          model_bundle = MODEL,
          mapping = MAPPING,
          counts_path = input$count_file$datapath,
          original_name = input$count_file$name,
          sample_id = sample_id,
          gene_id_type = input$gene_id_type,
          missing_gene_policy = if (isTRUE(input$omitted_rows_zero)) "zero_fill" else "fail"
        )
        incProgress(0.8, detail = "Scoring 56 signatures")
        out
      }),
      error = function(e) {
        error_message(conditionMessage(e))
        NULL
      }
    )
    if (!is.null(ans)) result(ans)
  })

  output$analysis_status <- renderUI({
    if (running()) return(div(class = "status-panel", h4("Running in browser...")))
    err <- error_message()
    if (!is.null(err)) return(div(class = "status-panel status-error", h4("Prediction stopped"), p(err)))
    x <- result()
    if (is.null(x)) {
      return(div(
        class = "status-panel",
        h4("Upload one sample"),
        p("Processing occurs locally in the browser; no Shiny compute server is used.")
      ))
    }
    q <- x$qc
    div(
      class = "status-panel",
      h4("QC status: ", status_badge(q$overall_QC[[1]])),
      p(sprintf(
        "Model-gene coverage: %.1f%% | Detected locked genes: %s/%s",
        100 * q$model_gene_coverage_fraction[[1]],
        q$n_detected_locked_genes[[1]], q$n_locked_rank_genes[[1]]
      ))
    )
  })

  output$risk_summary <- renderUI({
    x <- result(); req(x)
    p <- x$prediction
    tagList(
      div(
        class = "risk-grid",
        risk_card("Disease-free interval", p$DFI_frozen_log_hazard[[1]], p$DFI_DOG2_percentile[[1]], p$DFI_DOG2_tertile[[1]]),
        risk_card("Overall survival", p$OS_frozen_log_hazard[[1]], p$OS_DOG2_percentile[[1]], p$OS_DOG2_tertile[[1]])
      ),
      div(
        class = "interpretation-alert",
        strong("Important: "),
        "Percentiles are relative to DOG2 training animals and are not probabilities."
      )
    )
  })

  output$qc_table <- renderTable({ x <- result(); req(x); metric_table(x$qc) }, striped = TRUE, bordered = TRUE, spacing = "xs")
  output$mapping_table <- renderTable({ x <- result(); req(x); metric_table(x$mapping_qc) }, striped = TRUE, bordered = TRUE, spacing = "xs")

  contribution_table <- function(x, endpoint) {
    sr <- x$signature_results
    col <- paste0(endpoint, "_contribution")
    coef_col <- paste0(endpoint, "_coefficient")
    ord <- order(abs(sr[[col]]), decreasing = TRUE)
    sr <- sr[ord[seq_len(min(10, nrow(sr)))], , drop = FALSE]
    label <- if ("signature_name" %in% names(sr)) ifelse(is.na(sr$signature_name) | !nzchar(sr$signature_name), sr$signature_id, sr$signature_name) else sr$signature_id
    data.frame(
      Signature = label,
      Direction = ifelse(sr[[col]] >= 0, "Raises score", "Lowers score"),
      Standardized = round(sr$DOG2_standardized_score, 3),
      Coefficient = round(sr[[coef_col]], 4),
      Contribution = round(sr[[col]], 4),
      check.names = FALSE,
      stringsAsFactors = FALSE
    )
  }

  output$dfi_table <- renderTable({ x <- result(); req(x); contribution_table(x, "DFI") }, striped = TRUE, bordered = TRUE, spacing = "xs")
  output$os_table <- renderTable({ x <- result(); req(x); contribution_table(x, "OS") }, striped = TRUE, bordered = TRUE, spacing = "xs")
  output$all_table <- renderTable({
    x <- result(); req(x)
    sr <- x$signature_results
    label <- if ("signature_name" %in% names(sr)) ifelse(is.na(sr$signature_name) | !nzchar(sr$signature_name), sr$signature_id, sr$signature_name) else sr$signature_id
    source <- if ("signature_source" %in% names(sr)) sr$signature_source else ""
    data.frame(
      Signature = label,
      Source = source,
      `Raw singscore` = round(sr$raw_singscore, 4),
      `DOG2 standardized` = round(sr$DOG2_standardized_score, 3),
      `DFI contribution` = round(sr$DFI_contribution, 4),
      `OS contribution` = round(sr$OS_contribution, 4),
      check.names = FALSE,
      stringsAsFactors = FALSE
    )
  }, striped = TRUE, bordered = TRUE, spacing = "xs")

  output$download_prediction <- downloadHandler(
    filename = function() {
      x <- result(); req(x)
      paste0(safe_sample_id(x$prediction$sample_id[[1]]), "_all56_prediction.tsv")
    },
    content = function(file) {
      x <- result(); req(x)
      write.table(x$prediction, file, sep = "\t", row.names = FALSE, quote = FALSE)
    },
    contentType = "text/tab-separated-values; charset=utf-8"
  )


  # DOG2-SEND-PDF-TO-BROWSER
  observeEvent(
    prediction_result(),
    {
      result <- prediction_result()

      req(
        result,
        result$pdf_file,
        file.exists(result$pdf_file)
      )

      pdf_size <- file.info(
        result$pdf_file
      )$size[[1]]

      pdf_raw <- readBin(
        result$pdf_file,
        what = "raw",
        n = pdf_size
      )

      session$sendCustomMessage(
        "dog2-set-pdf",
        list(
          filename = basename(
            result$pdf_file
          ),
          base64 = jsonlite::base64_enc(
            pdf_raw
          )
        )
      )
    },
    ignoreInit = TRUE
  )

  output$download_pdf <- downloadHandler(
    filename = function() {
      x <- result(); req(x)
      paste0(safe_sample_id(x$prediction$sample_id[[1]]), "_all56_report.pdf")
    },
    content = function(file) {
      x <- result(); req(x)
      p <- x$prediction; q <- x$qc
      grDevices::pdf(file, width = 8.5, height = 11)
      on.exit(grDevices::dev.off(), add = TRUE)
      plot.new()
      text(0, 0.96, "DOG2 all56 server-free prediction", adj = c(0, 1), cex = 1.4, font = 2)
      text(0, 0.88, paste("Sample ID:", p$sample_id[[1]]), adj = c(0, 1))
      text(0, 0.82, paste("QC:", q$overall_QC[[1]]), adj = c(0, 1), font = 2)
      text(0, 0.72, sprintf("DFI log-hazard: %.3f", p$DFI_frozen_log_hazard[[1]]), adj = c(0, 1))
      text(0, 0.66, sprintf("DFI DOG2 percentile: %.1f", 100 * p$DFI_DOG2_percentile[[1]]), adj = c(0, 1))
      text(0, 0.58, sprintf("OS log-hazard: %.3f", p$OS_frozen_log_hazard[[1]]), adj = c(0, 1))
      text(0, 0.52, sprintf("OS DOG2 percentile: %.1f", 100 * p$OS_DOG2_percentile[[1]]), adj = c(0, 1))
      text(0, 0.38, sprintf("Model-gene coverage: %.1f%%", 100 * q$model_gene_coverage_fraction[[1]]), adj = c(0, 1))
      text(0, 0.22, "Research use only. Percentiles are not probabilities.", adj = c(0, 1), font = 2)
      text(0, 0.15, "Analysis executed locally in the browser using Shinylive/webR.", adj = c(0, 1), cex = 0.9)
    },
    contentType = "application/pdf"
  )
}

shinyApp(ui, server)

