          "
          // DOG2-IOS-PDF-SHARE
          window.dog2PdfFile = null;

          Shiny.addCustomMessageHandler('dog2-set-pdf', function(message) {
            const binary = atob(message.base64);
            const bytes = new Uint8Array(binary.length);
            for (let i = 0; i < binary.length; i++) {
              bytes[i] = binary.charCodeAt(i);
            }
            window.dog2PdfFile = new File(
              [bytes],
              message.filename,
