                  'The PDF report is not ready yet.'
                );
                return;
              }

              const binary =
                window.atob(base64);

              const bytes =
                new Uint8Array(binary.length);

              for (
                let i = 0;
                i < binary.length;
                i++
              ) {
                bytes[i] =
                  binary.charCodeAt(i);
              }

              const file =
                new File(
                  [bytes],
                  filename,
                  {
                    type: 'application/pdf'
                  }
                );

              const shareData = {
                files: [file],
                title: 'DOG2 prediction report'
              };

              try {
                if (
                  navigator.share &&
                  navigator.canShare &&
                  navigator.canShare(shareData)
                ) {
                  await navigator.share(
                    shareData
                  );

                  return;
                }
              } catch (error) {
                if (
                  error &&
                  error.name === 'AbortError'
                ) {
                  return;
                }

                console.error(
                  'PDF sharing failed:',
                  error
                );
              }

              const url =
                URL.createObjectURL(file);

              const link =
                document.createElement('a');

              link.href = url;
              link.download = filename;

              document.body.appendChild(link);
              link.click();
              link.remove();

              window.setTimeout(
                function() {
                  URL.revokeObjectURL(url);
                },
                60000
              );
            }
          );
          "
        )
      ),

