:root {
  --dog2-pwa-theme: #0f5d75;
  --dog2-pwa-text: #14232b;
  --dog2-pwa-surface: rgba(255, 255, 255, 0.97);
}

html,
body {
  min-height: 100%;
  background: #f4f7f9;
}

body {
  margin: 0;
  padding-top: env(safe-area-inset-top);
  padding-right: env(safe-area-inset-right);
  padding-bottom: env(safe-area-inset-bottom);
  padding-left: env(safe-area-inset-left);
}

.dog2-pwa-install {
  position: fixed;
  z-index: 2147483647;
  right: max(14px, env(safe-area-inset-right));
  bottom: max(14px, calc(env(safe-area-inset-bottom) + 8px));
  left: max(14px, env(safe-area-inset-left));
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  max-width: 680px;
  margin: 0 auto;
  padding: 14px 16px;
  color: var(--dog2-pwa-text);
  background: var(--dog2-pwa-surface);
  border: 1px solid rgba(15, 93, 117, 0.22);
  border-radius: 18px;
  box-shadow: 0 12px 36px rgba(20, 35, 43, 0.22);
  -webkit-backdrop-filter: blur(16px);
  backdrop-filter: blur(16px);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

.dog2-pwa-install__text {
  display: grid;
  gap: 4px;
  line-height: 1.35;
}

.dog2-pwa-install__text strong {
  font-size: 0.98rem;
}

.dog2-pwa-install__text span {
  color: #53636b;
  font-size: 0.84rem;
}

.dog2-pwa-install__actions {
  display: flex;
  flex: 0 0 auto;
  gap: 8px;
}

.dog2-pwa-install button {
  min-height: 38px;
  border-radius: 999px;
  padding: 7px 13px;
  font: inherit;
  font-size: 0.86rem;
  font-weight: 650;
  cursor: pointer;
}

.dog2-pwa-install__primary {
  color: #fff;
  background: var(--dog2-pwa-theme);
  border: 1px solid var(--dog2-pwa-theme);
}

.dog2-pwa-install__dismiss {
  color: #40515a;
  background: transparent;
  border: 1px solid #bdc9cf;
}

@media (max-width: 520px) {
  .dog2-pwa-install {
    align-items: stretch;
    flex-direction: column;
  }

  .dog2-pwa-install__actions,
  .dog2-pwa-install button {
    width: 100%;
  }
}

@media (display-mode: standalone) {
  body {
    overscroll-behavior-y: none;
    -webkit-tap-highlight-color: transparent;
  }
}

/* DOG2 Predictor — conservative PWA service worker
 *
 * IMPORTANT:
 * Shinylive/webR assets are deliberately NOT intercepted or cached here.
 * Those files are version-coupled and stale copies can make the runtime
 * request an app payload that no longer exists.
 */

const CACHE_PREFIX = "dog2-all56-pwa-shell-";
const CACHE_NAME = `${CACHE_PREFIX}20260730_110513`;

const SHELL_PATHS = new Set([
  "./manifest.webmanifest",
  "./pwa-shell.css",
  "./install-pwa.js",
  "./icons/apple-touch-icon.png",
  "./icons/favicon-32.png",
  "./icons/icon-192.png",
  "./icons/icon-512.png",
  "./icons/icon-maskable-512.png"
]);

self.addEventListener("install", (event) => {
  event.waitUntil(
    caches.open(CACHE_NAME).then((cache) =>
      cache.addAll(Array.from(SHELL_PATHS))
    )
  );
  self.skipWaiting();
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) =>
        Promise.all(
          keys
            .filter((key) =>
              (
                key.startsWith(CACHE_PREFIX) ||
                key.startsWith("dog2-all56-pwa-")
              ) &&
              key !== CACHE_NAME
            )
            .map((key) => caches.delete(key))
        )
      )
      .then(() => self.clients.claim())
  );
});

self.addEventListener("fetch", (event) => {
  const request = event.request;

  if (request.method !== "GET") return;

  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;

  // Only cache the small PWA shell files below.
  // All Shinylive/webR/runtime/app payload requests go directly to the network.
  const isShellAsset = Array.from(SHELL_PATHS).some(
    (path) => url.pathname.endsWith(path.slice(1))
  );

  if (!isShellAsset) return;

  event.respondWith(
    caches.match(request).then((cached) => {
      if (cached) return cached;

      return fetch(request).then((response) => {
        if (response && response.ok) {
          const copy = response.clone();
          caches.open(CACHE_NAME).then((cache) => cache.put(request, copy));
        }
        return response;
      });
    })
  );
});

/* DOG2 all56 Shinylive PWA service worker
 *
 * The small app shell is pre-cached. Other same-origin Shinylive/webR assets
 * are cached on first use, avoiding an enormous install-time download.
 */
const CACHE_PREFIX = "dog2-all56-pwa-";
const CACHE_NAME = `${CACHE_PREFIX}2026-07-29-v1`;

const APP_SHELL = [
  "./",
  "./index.html",
  "./manifest.webmanifest",
  "./pwa-shell.css",
  "./install-pwa.js",
  "./icons/apple-touch-icon.png",
  "./icons/icon-192.png",
  "./icons/icon-512.png",
  "./icons/icon-maskable-512.png"
];

self.addEventListener("install", (event) => {
  event.waitUntil(
    caches.open(CACHE_NAME).then((cache) => cache.addAll(APP_SHELL))
  );
  self.skipWaiting();
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches.keys().then((keys) =>
      Promise.all(
        keys
          .filter((key) => key.startsWith(CACHE_PREFIX) && key !== CACHE_NAME)
          .map((key) => caches.delete(key))
      )
    ).then(() => self.clients.claim())
  );
});

async function cacheResponse(request, response) {
  if (
    response &&
    response.ok &&
    response.status === 200 &&
    (response.type === "basic" || response.type === "cors")
  ) {
    const cache = await caches.open(CACHE_NAME);
    await cache.put(request, response.clone());
  }
  return response;
}

async function networkFirstNavigation(request) {
  try {
    const response = await fetch(request);
    return await cacheResponse(request, response);
  } catch (error) {
    return (
      (await caches.match(request)) ||
      (await caches.match("./index.html")) ||
      (await caches.match("./"))
    );
  }
}

async function staleWhileRevalidate(request, event) {
  const cached = await caches.match(request);
  const network = fetch(request)
    .then((response) => cacheResponse(request, response))
    .catch(() => null);

  if (cached) {
    event.waitUntil(network);
    return cached;
  }

  const response = await network;
  if (response) return response;

  return new Response("Resource unavailable offline.", {
    status: 503,
    headers: { "Content-Type": "text/plain; charset=utf-8" }
  });
}

self.addEventListener("fetch", (event) => {
  const request = event.request;

  if (request.method !== "GET") return;

  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;

  // Avoid storing partial responses. Shinylive normally requests full assets,
  // but this keeps Range behavior correct if a browser uses it.
  if (request.headers.has("range")) return;

  if (request.mode === "navigate") {
    event.respondWith(networkFirstNavigation(request));
    return;
  }

  event.respondWith(staleWhileRevalidate(request, event));
});

