// DOG2-PDF-OVERLAY
(function () {
  "use strict";

  let currentBlobUrl = null;

  function ensureOverlay() {
    let overlay = document.getElementById("dog2-pdf-overlay");

    if (overlay) {
      return overlay;
    }

    overlay = document.createElement("div");
    overlay.id = "dog2-pdf-overlay";
    overlay.hidden = true;

    overlay.innerHTML = [
      '<div id="dog2-pdf-toolbar">',
      '  <button id="dog2-pdf-return" type="button" class="btn btn-primary">',
      '    &larr; Return to predictor',
      "  </button>",
      '  <div id="dog2-pdf-title">DOG2 prediction report</div>',
      "</div>",
      '<div id="dog2-pdf-status" hidden>Preparing PDF report...</div>',
      '<iframe id="dog2-pdf-frame" title="DOG2 PDF report" src="about:blank"></iframe>'
    ].join("");

    document.body.appendChild(overlay);
    return overlay;
  }

  function releaseBlobUrl() {
    if (currentBlobUrl) {
      URL.revokeObjectURL(currentBlobUrl);
      currentBlobUrl = null;
    }
  }

  function closeOverlay() {
    const overlay = ensureOverlay();
    const frame = document.getElementById("dog2-pdf-frame");
    const status = document.getElementById("dog2-pdf-status");

    overlay.hidden = true;
    frame.src = "about:blank";
    status.hidden = true;
    document.body.classList.remove("dog2-pdf-open");
    releaseBlobUrl();
  }

  async function openPdfFromLink(link) {
    const href = link.getAttribute("href");

    if (!href || href === "#") {
      window.alert("The PDF report is not ready yet.");
      return;
    }

    const overlay = ensureOverlay();
    const frame = document.getElementById("dog2-pdf-frame");
    const status = document.getElementById("dog2-pdf-status");

    releaseBlobUrl();
    frame.src = "about:blank";
    status.textContent = "Preparing PDF report...";
    status.hidden = false;
    overlay.hidden = false;
    document.body.classList.add("dog2-pdf-open");

    try {
      const absoluteUrl = new URL(href, window.location.href).href;
      const response = await fetch(absoluteUrl);

      if (!response.ok) {
        throw new Error("PDF request failed: HTTP " + response.status);
      }

      const bytes = await response.arrayBuffer();
      const pdfBlob = new Blob(
        [bytes],
        { type: "application/pdf" }
      );

      currentBlobUrl = URL.createObjectURL(pdfBlob);
      frame.src = currentBlobUrl;
      status.hidden = true;
    } catch (error) {
      console.error("DOG2 PDF overlay error:", error);
      status.textContent =
        "The PDF could not be displayed inside the app. Return to the predictor and try again.";
      status.hidden = false;
    }
  }

  document.addEventListener(
    "click",
    function (event) {
      const returnButton =
        event.target.closest("#dog2-pdf-return");

      if (returnButton) {
        event.preventDefault();
        event.stopImmediatePropagation();
        closeOverlay();
        return;
      }

      const pdfLink =
        event.target.closest("#download_pdf");

      if (!pdfLink) {
        return;
      }

      event.preventDefault();
      event.stopImmediatePropagation();
      pdfLink.removeAttribute("download");
      openPdfFromLink(pdfLink);
    },
    true
  );

  window.addEventListener(
    "pagehide",
    releaseBlobUrl
  );
})();

// DOG2-IOS-TSV-SHARE
(function () {
  "use strict";

  let cachedHref = null;
  let cachedFile = null;
  let prefetchPromise = null;

  function isIOSDevice() {
    return (
      /iPad|iPhone|iPod/.test(navigator.userAgent) ||
      (
        navigator.platform === "MacIntel" &&
        navigator.maxTouchPoints > 1
      )
    );
  }

  function isStandaloneApp() {
    return (
      window.navigator.standalone === true ||
      window.matchMedia("(display-mode: standalone)").matches
    );
  }

  function shouldIntercept() {
    return isIOSDevice() && isStandaloneApp();
  }

  function responseFilename(response, link) {
    const disposition =
      response.headers.get("content-disposition") || "";

    let match = disposition.match(
      /filename\*=UTF-8''([^;]+)/i
    );

    if (match && match[1]) {
      try {
        return decodeURIComponent(match[1]);
      } catch (error) {
        return match[1];
      }
    }

    match = disposition.match(
      /filename="?([^";]+)"?/i
    );

    if (match && match[1]) {
      return match[1];
    }

    const linkName =
      link.getAttribute("download") || "";

    if (
      linkName &&
      !linkName.toLowerCase().endsWith(".html")
    ) {
      return linkName;
    }

    return "DOG2_all56_prediction.tsv";
  }

  async function makeTsvFile(link) {
    const href = link.getAttribute("href");

    if (!href || href === "#") {
      throw new Error("TSV link is not ready.");
    }

    if (cachedFile && cachedHref === href) {
      return cachedFile;
    }

    if (prefetchPromise && cachedHref === href) {
      return prefetchPromise;
    }

    cachedHref = href;

    prefetchPromise = (async function () {
      const url = new URL(
        href,
        window.location.href
      ).href;

      const response = await fetch(
        url,
        {
          credentials: "same-origin",
          cache: "no-store"
        }
      );

      if (!response.ok) {
        throw new Error(
          "TSV request failed: HTTP " +
          response.status
        );
      }

      const text = await response.text();
      const beginning =
        text.trimStart().slice(0, 100).toLowerCase();

      if (
        beginning.startsWith("<!doctype html") ||
        beginning.startsWith("<html")
      ) {
        throw new Error(
          "The generated download was HTML, not TSV."
        );
      }

      let filename =
        responseFilename(response, link);

      if (!filename.toLowerCase().endsWith(".tsv")) {
        filename += ".tsv";
      }

      cachedFile = new File(
        [text],
        filename,
        {
          type:
            "text/tab-separated-values;charset=utf-8"
        }
      );

      return cachedFile;
    })();

    try {
      return await prefetchPromise;
    } finally {
      prefetchPromise = null;
    }
  }

  function findTsvLink() {
    return document.getElementById(
      "download_prediction"
    );
  }

  function prefetchIfReady() {
    if (!shouldIntercept()) {
      return;
    }

    const link = findTsvLink();

    if (
      !link ||
      !link.getAttribute("href") ||
      link.getAttribute("href") === "#"
    ) {
      return;
    }

    makeTsvFile(link).catch(function (error) {
      console.debug(
        "DOG2 TSV prefetch not ready:",
        error
      );
    });
  }

  async function shareTsv(link) {
    try {
      const file = await makeTsvFile(link);
      const data = {
        files: [file],
        title: "DOG2 prediction TSV"
      };

      if (
        navigator.share &&
        navigator.canShare &&
        navigator.canShare(data)
      ) {
        await navigator.share(data);
        return;
      }

      throw new Error(
        "File sharing is unavailable on this device."
      );
    } catch (error) {
      if (
        error &&
        error.name === "AbortError"
      ) {
        return;
      }

      console.error(
        "DOG2 TSV share error:",
        error
      );

      window.alert(
        "The TSV could not be opened. " +
        "Please try again, then choose " +
        "\"Save to Files\" from the iPhone share sheet."
      );
    }
  }

  document.addEventListener(
    "click",
    function (event) {
      const link = event.target.closest(
        "#download_prediction"
      );

      if (!link || !shouldIntercept()) {
        return;
      }

      event.preventDefault();
      event.stopImmediatePropagation();
      shareTsv(link);
    },
    true
  );

  const observer = new MutationObserver(
    prefetchIfReady
  );

  observer.observe(
    document.documentElement,
    {
      childList: true,
      subtree: true,
      attributes: true,
      attributeFilter: ["href", "download"]
    }
  );

  window.setInterval(
    prefetchIfReady,
    1000
  );

  document.addEventListener(
    "DOMContentLoaded",
    prefetchIfReady
  );
})();
